<?php
$services = ['vente-terrain'=>'Vente de terrains','construction-residentielle'=>'Construction résidentielle','amenagement-paysager'=>'Aménagement paysager','clotures'=>'Fabrication de clôtures','conception'=>'Conception','extensions'=>'Extensions de maison','electricite'=>'Installations électriques','amenagement-exterieur'=>'Aménagement extérieur'];
$selectedService = (string) ($_GET['service'] ?? '');
if (!isset($services[$selectedService])) { $selectedService = ''; }
$reviews = [];
$summary = ['average'=>0,'total'=>0];
if ($selectedService !== '') {
    $summaryStmt = db()->prepare("SELECT AVG(note) AS average, COUNT(*) AS total FROM avis_terrains WHERE type_cible='service' AND cible_service=:service AND statut='publie'");
    $summaryStmt->execute(['service'=>$selectedService]);
    $summary = $summaryStmt->fetch() ?: $summary;
    $reviewsStmt = db()->prepare("SELECT nom,note,commentaire,date_creation FROM avis_terrains WHERE type_cible='service' AND cible_service=:service AND statut='publie' ORDER BY date_creation DESC LIMIT 30");
    $reviewsStmt->execute(['service'=>$selectedService]);
    $reviews = $reviewsStmt->fetchAll();
}
?>
<section class="page-intro review-intro"><span class="eyebrow">PAROLES DE CLIENTS</span><h1>Votre expérience compte.</h1><p>Choisissez un service pour lire les retours publiés ou partager votre expérience.</p></section><section class="reviews-section service-reviews"><div class="service-review-layout"><div><form class="service-select glass-filter service-filter-form" method="get"><input type="hidden" name="page" value="avis"><label>Service concerné<select name="service"><option value="">Sélectionner un service</option><?php foreach ($services as $slug=>$label): ?><option value="<?= e($slug) ?>" <?= $selectedService===$slug?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button class="button button-outline">Afficher les avis</button></form><?php if ($selectedService): ?><div class="reviews-heading"><h2><?= e($services[$selectedService]) ?></h2><?= star_rating((float)($summary['average'] ?? 0),(int)$summary['total']) ?></div><div class="review-list"><?php if ($reviews): foreach ($reviews as $review): ?><article class="review-card"><div class="review-card-head"><strong><?= e($review['nom']) ?></strong><?= star_rating((float)$review['note']) ?></div><p><?= nl2br(e($review['commentaire'])) ?></p><time><?= e(date('d/m/Y',strtotime($review['date_creation']))) ?></time></article><?php endforeach; else: ?><p class="empty-reviews">Aucun avis publié pour ce service.</p><?php endif; ?></div><?php else: ?><div class="empty-state compact"><h3>Des retours vérifiés par notre équipe.</h3><p>Les avis restent modérés avant publication afin de préserver un espace utile et respectueux.</p></div><?php endif; ?></div><form class="review-form glass-filter" method="post" action="?page=avis"><?= csrf_field() ?><input type="hidden" name="action" value="submit_review"><input type="hidden" name="type_cible" value="service"><label class="honeypot" aria-hidden="true">Ne pas remplir<input name="website" tabindex="-1" autocomplete="off"></label><span class="eyebrow">VOTRE RETOUR</span><h2>Évaluer un service</h2><label>Service<select name="cible_service" required><option value="">Sélectionner un service</option><?php foreach ($services as $slug=>$label): ?><option value="<?= e($slug) ?>" <?= $selectedService===$slug?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Votre nom<input name="nom" maxlength="120" required autocomplete="name"></label><fieldset class="star-picker"><legend>Votre note</legend><?php for ($star=5;$star>=1;$star--): ?><label><input type="radio" name="note" value="<?= $star ?>" required><span aria-label="<?= $star ?> sur 5">★</span></label><?php endfor; ?></fieldset><label>Votre avis<textarea name="commentaire" maxlength="2000" rows="5" required placeholder="Partagez votre expérience..."></textarea></label><button class="button button-green">Envoyer pour modération <span>↗</span></button><small>Les avis sont publiés après vérification.</small></form></div></section>